const CATALOGUES = { en, de, fr };

/**
 * The workbook's words in one language. English is the source, and is what an
 * engagement with no language recorded gets.
 *
 * @param {string} [language]
 * @returns {typeof en}
 */
export function words(language) {
  if (isEnglish(language)) return en;
  return CATALOGUES[String(language).toLowerCase()] ?? en;
}

export const WORKBOOK_LANGUAGES = Object.keys(CATALOGUES);
